	// (GET /dns/settings)
	GetDnsSettings(c *gin.Context)
	// UpdateDnsSettings 更新 DNS 行为参数（渲染→checkconf→reload）
	// (PUT /dns/settings)
	UpdateDnsSettings(c *gin.Context)
